const paymentStatus={creating:'Creating payment',review:'Needs support review',waiting:'Awaiting payment',confirming:'Confirming on network',confirmed:'Confirmed · settlement pending',sending:'Settlement in progress',partially_paid:'Partial payment · contact support',failed:'Failed',refunded:'Refunded',expired:'Expired',credited:'Paid · credited'};
let checkoutRequest=null;
function commerceLogin(){if(session?.user)return true;$('#app').innerHTML='<section class="page-state"><h1>Sign in to continue</h1><p>Your payments and support requests belong to your account.</p><a class="button dark" href="/signin-with-chatgpt?return_to='+encodeURIComponent(location.pathname)+'" target="_top">Sign in with ChatGPT</a></section>'+footer();rulesBindings();return false;}
function commerceShell(title,description,body){document.title=title+' — Linkdid';$('#app').innerHTML='<section class="account-wrap commerce"><div class="account-subnav"><a href="/">Sandbox board</a><a href="/paid">Paid board</a><a href="/account">My dashboard</a><a href="/billing">Payments</a><a href="/support">Help</a></div><h1>'+title+'</h1><p>'+description+'</p>'+body+'</section>'+footer();rulesBindings();imageFallbacks();}
async function billing(){
 if(!commerceLogin())return;
 const [config,data]=await Promise.all([api('/api/crypto/config'),api('/api/crypto/orders')]);
 const messages={waiting:'Send only the exact currency on the network shown. Include network fees separately. Then check the payment status.',partially_paid:'The provider reported a partial payment. Contact support before sending more.',expired:'This payment expired. Do not send funds to this address.',credited:'Your payment has been verified and your paid placement total has increased.',review:'Do not start duplicate payments. Open a support request with this order ID.'};
 const rows=data.orders.map(o=>'<article class="payment-order"><div class="panel-header"><h3>'+money(o.amount)+' placement credit</h3><span class="payment-status '+(o.status==='credited'?'success':'')+'">'+esc(paymentStatus[o.status]||o.status)+'</span></div><p>'+esc(o.network)+' · '+esc(date(o.created))+'</p><p class="order-id">Order '+esc(o.id)+'</p><p>'+esc(messages[o.status]||'Payment has not been credited yet. Check again after network confirmation.')+'</p>'+(o.address&&o.status==='waiting'?'<div class="payment-instructions"><label>Exact amount<input readonly value="'+esc(o.payAmount)+' '+esc(o.currency.toUpperCase())+'"></label><label>Network<input readonly value="'+esc(o.network)+'"></label><label>Payment address<input readonly value="'+esc(o.address)+'"></label><button class="secondary-btn" data-copy="'+esc(o.address)+'">Copy address</button>'+(o.extraId?'<label>Required memo / tag<input readonly value="'+esc(o.extraId)+'"></label>':'')+(o.expires?'<p>Provider expiry: '+esc(o.expires)+'</p>':'<p>Check status before sending. Quotes may expire.</p>')+'</div>':'')+'<div class="profile-actions">'+(o.paymentId&&o.status!=='credited'?'<button class="secondary-btn" data-check="'+o.id+'">Check payment status</button>':'')+(o.status==='credited'?'<a class="secondary-btn" href="/api/crypto/orders/'+o.id+'/receipt">Download receipt</a>':'')+'<a href="/support?order='+o.id+'">Get help</a></div></article>').join('');
 commerceShell('Your payments','Crypto payments purchase sponsored placement on the paid leaderboard. Sandbox bids stay separate.',
 '<div class="account-grid"><section class="panel"><span class="eyebrow">CRYPTO CHECKOUT</span><h2>Add to your paid total</h2>'+
 (!config.enabled?'<div class="status-message"><b>Crypto checkout is not activated yet.</b><p>The merchant payment account must be connected before you can pay. No wallet address or payment request has been created.</p></div>':!account?.profile?'<p>Create your profile before purchasing placement.</p><a class="button dark" href="/account">Create profile</a>':
 '<form id="crypto-form"><label>Placement credit in USD<input name="amount" type="number" min="10" max="10000" step="1" required value="25"></label><label>Currency and network<select name="currency" required>'+config.currencies.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.label)+'</option>').join('')+'</select></label><p>Provider minimums and network fees may apply. Your total increases after payment is verified; rank can change while payment is pending.</p><label class="terms-check"><input type="checkbox" name="accepted" required> I accept the <a target="_blank" rel="noopener" href="'+esc(config.terms)+'">purchase and refund terms</a>.</label><p id="checkout-error" class="error-message" role="alert"></p><button class="button dark" '+(!config.currencies.length?'disabled':'')+'>Create crypto payment →</button></form>')+
 '<div class="payment-methods"><span>₿ Bitcoin</span><span>Ξ Ethereum</span><span>₮ USDT</span></div><p>Available networks are confirmed at checkout. Payment processing: NOWPayments.</p><a href="/paid">View paid leaderboard →</a></section><section class="panel"><h2>Payment history</h2>'+(rows||'<div class="empty-payment"><h3>No payments yet</h3><p>Your payment instructions, status and receipts will appear here.</p></div>')+'</section></div>');
 if($('#crypto-form'))$('#crypto-form').onsubmit=async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button'),values={amount:Number(f.elements.amount.value),currency:f.elements.currency.value,accepted:f.elements.accepted.checked};button.disabled=true;$('#checkout-error').textContent='';if(!checkoutRequest||checkoutRequest.amount!==values.amount||checkoutRequest.currency!==values.currency)checkoutRequest={...values,id:crypto.randomUUID()};try{await api('/api/crypto/orders',checkoutRequest);checkoutRequest=null;await billing();toast('Payment created. Review the network and amount carefully.')}catch(err){$('#checkout-error').textContent=err.message+' Your order may appear in payment history; refresh before retrying.'}finally{button.disabled=false}};
 document.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/crypto/orders/'+b.dataset.check+'/check',{});await billing()}catch(e){toast(e.message)}finally{b.disabled=false}});
 document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('Payment address copied.')}catch{toast('Select the address field and copy it manually.')}});
}
async function paidBoard(){const {profiles}=await api('/api/paid');commerceShell('The paid spotlight','Ranked by verified crypto placement payments. Your position stays until someone outbids your total.',
 '<div class="paid-intro"><span class="eyebrow">SPONSORED PLACEMENT</span><a class="button dark" href="/billing">Pay with crypto →</a></div><div>'+ (profiles.length?profiles.map((p,i)=>'<article class="profile '+(i===0?'first':'')+'"><span class="rank">#'+(i+1)+'</span>'+avatar(p)+'<div><h2><a href="/profile/'+p.id+'">'+esc(p.name)+'</a></h2><p>'+esc(p.headline)+'</p><span class="tag">'+esc(p.category)+'</span></div><div class="bid-area"><div class="bid-total">'+money(p.bid)+'</div><span>Verified total</span><a class="bid-button" href="/billing">Top up →</a></div></article>').join(''):'<section class="panel page-state"><h2>The first paid spot is open.</h2><p>No verified paid placements yet. Test bids on the sandbox board do not count here.</p></section>')+'</div><p>Ties use profile creation time, then profile ID. Paid placement affects Linkdid only and does not guarantee traffic or clients.</p>');}
async function supportPage(){if(!commerceLogin())return;const data=await api('/api/support');commerceShell('How can we help?','Track a payment issue, request a refund review, or report a profile.',
 '<div class="account-grid"><section class="panel"><h2>Send a support request</h2><p>Requests are saved for the site operator. No email is sent automatically.</p><form id="support-form"><label>Subject<input name="subject" required maxlength="100" value="'+esc(new URLSearchParams(location.search).get('order')?'Payment '+new URLSearchParams(location.search).get('order'):'')+'"></label><label>Details<textarea name="message" required maxlength="2000" rows="6" placeholder="Describe what happened. Include your order ID for payment issues. Never include passwords, private keys or wallet recovery phrases."></textarea></label><p id="support-error" class="error-message" role="alert"></p><button class="button dark">Submit request</button></form></section><section class="panel"><h2>Your requests</h2>'+(data.tickets.map(t=>'<article class="payment-order"><div class="panel-header"><h3>'+esc(t.subject)+'</h3><span class="payment-status">'+esc(t.status)+'</span></div><p class="support-message">'+esc(t.message)+'</p><p>'+esc(date(t.created))+'</p><small>Reference: '+t.id+'</small></article>').join('')||'<p>No requests yet.</p>')+'</section></div><section class="panel"><h2>Common questions</h2><details><summary>Does this improve my LinkedIn ranking?</summary><p>No. Sponsored placement applies only to the Linkdid leaderboard.</p></details><details><summary>When does my paid rank change?</summary><p>After NOWPayments reports the payment finished and you check its status on the Payments page. Pending and partial payments do not receive credit.</p></details><details><summary>What happens when I am outbid?</summary><p>Your listing stays visible. Add to your total to move up again. Notifications appear in your dashboard.</p></details><details><summary>Can I request a refund?</summary><p>Submit a request with the order ID. Eligibility follows the purchase terms shown at checkout; submitting a request does not approve or execute a refund.</p></details><details><summary>Why is my LinkedIn photo not imported?</summary><p>LinkedIn account connection is not activated yet. You can upload a photo from your dashboard.</p></details></section>');
 $('#support-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/support',Object.fromEntries(new FormData(e.target)));await supportPage();toast('Support request saved.')}catch(e){$('#support-error').textContent=e.message}finally{b.disabled=false}};
}
function aboutPage(){commerceShell('A spotlight for professionals.','Linkdid helps people discover LinkedIn professionals through transparent sponsored placement.', '<section class="panel"><h2>How Linkdid works</h2><ol><li>Create your profile and choose a specialty.</li><li>Try bidding on the sandbox leaderboard.</li><li>When crypto checkout is activated, purchase placement on the separate paid board.</li><li>Track your rank, outbound clicks, payments and outbid notifications.</li></ol><p>Higher cumulative bids rank first. You stay listed when outbid and can add to your total. Placement is advertising, not an endorsement of professional ability.</p><a class="button dark" href="/account">Build your profile →</a></section>');}
async function adminPage(){if(!commerceLogin())return;if(!session.admin){commerceShell('Operator access','This page is restricted to the configured site administrator.','<section class="panel"><p>Administrator access has not been granted to this account.</p></section>');return}const {tickets}=await api('/api/admin/support');commerceShell('Support inbox','Review customer requests. Status changes notify the account in their dashboard.','<section class="panel">'+(tickets.map(t=>'<article class="payment-order"><h3>'+esc(t.subject)+'</h3><p class="support-message">'+esc(t.message)+'</p><p>'+esc(date(t.created))+' · '+esc(t.id)+'</p><label>Request status<select data-ticket="'+t.id+'">'+['open','in_review','resolved'].map(s=>'<option value="'+s+'" '+(s===t.status?'selected':'')+'>'+s.replace('_',' ')+'</option>').join('')+'</select></label></article>').join('')||'<p>No requests yet.</p>')+'</section>');document.querySelectorAll('[data-ticket]').forEach(s=>s.onchange=async()=>{s.disabled=true;try{await api('/api/admin/support',{id:s.dataset.ticket,status:s.value});toast('Request status updated.')}catch(e){toast(e.message)}finally{s.disabled=false}});}
async function commerceRoute(){if(location.pathname==='/admin'){await adminPage();return true}if(location.pathname==='/billing'){await billing();return true}if(location.pathname==='/paid'){await paidBoard();return true}if(location.pathname==='/support'){await supportPage();return true}if(location.pathname==='/about'){aboutPage();return true}return false;}
